{
  "name": "rf_arp_request_handle",
  "confidence": "medium",
  "docstring": "Inspect a received frame payload for an ARP request whose target IPv4 matches the local VIF address and, on match, map the request into the RF calibration context.",
  "subsystem": "rf",
  "var_renames": {
    "a2": "vif_ip_addr",
    "a3": "raw_pkt_base",
    "v6": "payload_offset",
    "v7": "payload_ptr",
    "v10": "arp_op_high",
    "v12": "arp_operation",
    "v13": "arp_target_ip"
  },
  "struct_hints": [
    {
      "offset": 1,
      "meaning": "byte 1 of raw packet/frame header; bit 0x40 selects extra payload offset"
    },
    {
      "offset": 30,
      "meaning": "payload offset 0x1E: first byte of ARP EtherType (0x08)"
    },
    {
      "offset": 31,
      "meaning": "payload offset 0x1F: second byte of ARP EtherType (0x06)"
    },
    {
      "offset": 38,
      "meaning": "ARP operation high byte, expected zero"
    },
    {
      "offset": 39,
      "meaning": "ARP operation low byte: 1 request, 2 response"
    },
    {
      "offset": 40,
      "meaning": "ARP sender hardware address (MAC) field"
    },
    {
      "offset": 56,
      "meaning": "ARP target protocol address field start (IPv4 target IP)"
    }
  ]
}
